                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="label" tick={{ fontSize: 11 }} />
                    <YAxis tickFormatter={(v) => `${v}%`} domain={[0, 100]} />
                    <Tooltip
                      formatter={(v) =>
                        typeof v === "number" ? fmtPct(v, 1) : String(v)
                      }
                    />
                    <Area
                      type="monotone"
                      dataKey="sharePct"
                      name="Cumulative share"
                      fill={SKY}
                      fillOpacity={0.2}
                      stroke={SKY}
                      strokeWidth={2}
                    />
                    {showEqual && (
                      <Line
                        type="monotone"
                        dataKey="equalPct"
                        name="Equality"
                        stroke="#94a3b8"
                        strokeDasharray="4 4"
                        dot={false}
                      />
                    )}
                  </ComposedChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
        </div>
      )}

      {view === "liquid" && (
        <div className="space-y-6">
          <div className="flex flex-wrap gap-4">
            <ToggleGroup
              label="Delta filter"
              value={deltaFilter}
              onChange={setDeltaFilter}
              options={[
                { id: "all", label: "All meters" },
                { id: "moved", label: "Moved" },
                { id: "sticky", label: "Sticky tip" },
              ]}
            />
          </div>
          <div className="grid gap-6 lg:grid-cols-2">
            <ChartCard
              title="Liquid parking after official MMF print"
              subtitle={`Deposits still ~${fmtPct(HEADLINE.depositsShareOfLiquidPct, 1)} of the pair vs ICI ${fmtTn(HEADLINE.mmfTn)}`}
            >
              <div className="h-80 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={liquidPie}
                      dataKey="value"
                      nameKey="name"
                      cx="50%"
                      cy="50%"
                      innerRadius={58}
                      outerRadius={100}
                      paddingAngle={2}
                      label={({ name, value }) => `${name} ${value}%`}
                    >
                      {liquidPie.map((s) => (
                        <Cell key={s.name} fill={s.fill} />
                      ))}
                    </Pie>
                    <Tooltip
                      formatter={(v, _n, item) => {
                        const tn = (item?.payload as { tn?: number })?.tn;
                        return typeof v === "number"
                          ? `${fmtPct(v, 1)}${tn != null ? ` (${fmtTn(tn)})` : ""}`
                          : String(v);
                      }}
                    />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>

            <ChartCard
              title="MMF path into the Aug correction"
              subtitle="Q3 theme restatement ??? official Aug 19 week ($7.928T)"
            >
              <div className="h-80 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ComposedChart
