                </ResponsiveContainer>
              </div>
            </ChartCard>

            <ChartCard
              title="Wealth buckets (unchanged tip)"
              subtitle="DFA-style stock still ~$52T in the top 1%"
            >
              <div className="h-80 w-full min-w-0">
