                        <Cell key={r.bucket} fill={r.fill} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>

            <ChartCard
              title="Debt share vs stress clock"
              subtitle="High-stress products are small sleeves of $18.93T"
            >
              <div className="h-80 w-full min-w-0">
