                      formatter={(v) =>
                        typeof v === "number" ? fmtPct(v, 1) : String(v)
                      }
                    />
                    <Bar dataKey="sharePct" name="Share %" radius={[4, 4, 0, 0]}>
                      {WEALTH_SHARES.map((r) => (
                        <Cell key={r.id} fill={r.fill} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
        </div>
      )}

      {view === "mirror" && (
        <div className="space-y-6">
          <div className="flex flex-wrap gap-4">
            <ToggleGroup
              label="Sort mirror"
              value={mirrorMetric}
              onChange={setMirrorMetric}
              options={[
                { id: "equitySharePct", label: "By equities" },
                { id: "revolvingSharePct", label: "By revolving" },
                { id: "depositSharePct", label: "By deposits" },
              ]}
            />
          </div>
          <div className="grid gap-6 lg:grid-cols-2">
            <ChartCard
              title="Save vs borrow mirror"
              subtitle="Top 1% owns ~54% of equities and ~5% of revolving"
            >
              <div className="h-80 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    data={SAVE_BORROW_MIRROR}
                    margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                    <YAxis tickFormatter={(v) => `${v}%`} />
                    <Tooltip
                      formatter={(v) =>
                        typeof v === "number" ? fmtPct(v, 0) : String(v)
                      }
                    />
                    <Bar
                      dataKey="equitySharePct"
                      name="Equities"
                      fill={VIOLET}
                      radius={[4, 4, 0, 0]}
                    />
                    <Bar
                      dataKey="revolvingSharePct"
                      name="Revolving"
                      fill={AMBER}
                      radius={[4, 4, 0, 0]}
                    />
                    <Bar
                      dataKey="depositSharePct"
                      name="Deposits"
                      fill={SKY}
                      radius={[4, 4, 0, 0]}
                    />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>

            <ChartCard
              title="Single-lens rank"
              subtitle="Toggle sort to flip who looks 'democratic'"
            >
              <div className="h-80 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    data={mirrorBars}
                    layout="vertical"
                    margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis type="number" tickFormatter={(v) => `${v}%`} />
                    <YAxis
                      type="category"
                      dataKey="short"
                      width={72}
                      tick={{ fontSize: 12 }}
                    />
                    <Tooltip
                      formatter={(v) =>
                        typeof v === "number" ? fmtPct(v, 0) : String(v)
                      }
                    />
                    <Bar dataKey={mirrorMetric} radius={[0, 4, 4, 0]}>
                      {mirrorBars.map((r) => (
                        <Cell key={r.bucket} fill={r.fill} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>

            <ChartCard
              title="Debt share vs stress clock"
              subtitle="High-stress products are small sleeves of $18.93T"
            >
              <div className="h-80 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ComposedChart
                    data={DEBT_STRESS_SLEEVES}
                    margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                    <YAxis
                      yAxisId="left"
                      tickFormatter={(v) => `${v}%`}
                      domain={[0, 80]}
                    />
                    <YAxis
                      yAxisId="right"
                      orientation="right"
                      tickFormatter={(v) => `${v}%`}
                      domain={[0, 14]}
                    />
                    <Tooltip />
                    <Bar
                      yAxisId="left"
                      dataKey="debtSharePct"
                      name="Debt share %"
                      fill={SKY}
                      radius={[4, 4, 0, 0]}
                    />
                    <Line
                      yAxisId="right"
                      type="monotone"
                      dataKey="stressPct"
                      name="Stress %"
                      stroke={ROSE}
                      strokeWidth={2}
                      dot={{ r: 4 }}
                    />
                  </ComposedChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>

            <ChartCard
              title="Equity tip vs revolving invert"
              subtitle="Same households, opposite Lorenz geometry"
            >
              <div className="h-80 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ScatterChart margin={{ top: 12, right: 16, left: 8, bottom: 12 }}>
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis
                      type="number"
                      dataKey="equitySharePct"
                      name="Equity %"
                      unit="%"
                      domain={[0, 60]}
                    />
                    <YAxis
                      type="number"
                      dataKey="revolvingSharePct"
                      name="Revolving %"
                      unit="%"
                      domain={[0, 50]}
                    />
                    <ZAxis range={[100, 260]} />
                    <Tooltip cursor={{ strokeDasharray: "3 3" }} />
                    <Scatter data={SAVE_BORROW_MIRROR} name="Buckets">
                      {SAVE_BORROW_MIRROR.map((p) => (
                        <Cell key={p.bucket} fill={p.fill} />
                      ))}
                    </Scatter>
                  </ScatterChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
        </div>
      )}

      {view === "firms" && (
        <div className="space-y-6">
          <div className="flex flex-wrap gap-4">
            <ToggleGroup
              label="Debt products"
              value={productMode}
              onChange={setProductMode}
              options={[
                { id: "share", label: "Share %" },
                { id: "stock", label: "$ trillions" },
              ]}
            />
          </div>
          <div className="grid gap-6 lg:grid-cols-2">
            <ChartCard
              title="Issuer cumulative ladder"
              subtitle={`Top-1 ${fmtPct(HEADLINE.top1IssuerSharePct, 0)} ?? Top-3 ${fmtPct(HEADLINE.top3IssuerSharePct, 0)} ?? Top-5 ${fmtPct(HEADLINE.top5IssuerSharePct, 0)}`}
            >
              <div className="h-80 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <ComposedChart
                    data={ISSUER_CUMULATIVE}
                    margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="label" />
                    <YAxis tickFormatter={(v) => `${v}%`} domain={[0, 100]} />
                    <Tooltip
                      formatter={(v) =>
                        typeof v === "number" ? fmtPct(v, 0) : String(v)
                      }
                    />
                    <Area
                      type="monotone"
                      dataKey="sharePct"
                      name="Cumulative purchase $"
                      fill={TEAL}
                      fillOpacity={0.25}
                      stroke={TEAL}
                      strokeWidth={2}
                    />
                    <Line
                      type="monotone"
                      dataKey="sharePct"
                      stroke={TEAL}
                      strokeWidth={2}
                      dot={{ r: 4 }}
                    />
                  </ComposedChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>

            <ChartCard
              title="Issuer purchase-volume mix"
              subtitle="Nilson-style general-purpose ranks ??? moderate firm HHI story"
            >
              <div className="h-80 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <PieChart>
                    <Pie
                      data={issuerPie}
                      dataKey="value"
                      nameKey="name"
                      cx="50%"
                      cy="50%"
                      outerRadius={100}
                      label={({ name, value }) => `${name} ${value}%`}
                    >
                      {issuerPie.map((s) => (
                        <Cell key={s.name} fill={s.fill} />
                      ))}
                    </Pie>
                    <Tooltip
                      formatter={(v) =>
                        typeof v === "number" ? fmtPct(v, 0) : String(v)
                      }
                    />
                  </PieChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>

            <ChartCard
              title="Debt-product concentration"
              subtitle={`Mortgage ${fmtPct(HEADLINE.top1DebtProductSharePct, 1)} of NY Fed ${fmtTn(HEADLINE.totalDebtTn)}`}
            >
              <div className="h-80 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    data={debtBars}
                    layout="vertical"
                    margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis
                      type="number"
                      tickFormatter={(v) =>
                        productMode === "share" ? `${v}%` : `$${v}T`
                      }
                    />
                    <YAxis
                      type="category"
                      dataKey="short"
                      width={72}
                      tick={{ fontSize: 12 }}
                    />
                    <Tooltip
                      formatter={(v) => {
                        if (typeof v !== "number") return String(v);
                        return productMode === "share"
                          ? fmtPct(v, 1)
                          : fmtTn(v);
                      }}
                    />
                    <Bar
                      dataKey={productMode === "share" ? "sharePct" : "stockTn"}
                      radius={[0, 4, 4, 0]}
                    >
                      {debtBars.map((r) => (
                        <Cell key={r.product} fill={r.fill} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>

            <ChartCard
              title="Issuer ranked bars"
              subtitle="Chase leads; long tail still ~29%"
            >
              <div className="h-80 w-full min-w-0">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart
                    data={ISSUER_SHARES}
                    margin={{ top: 8, right: 16, left: 8, bottom: 8 }}
                  >
                    <CartesianGrid strokeDasharray="3 3" stroke="#e2e8f0" />
                    <XAxis dataKey="short" tick={{ fontSize: 11 }} />
                    <YAxis tickFormatter={(v) => `${v}%`} />
                    <Tooltip
                      formatter={(v) =>
                        typeof v === "number" ? fmtPct(v, 0) : String(v)
                      }
                    />
                    <Bar dataKey="sharePct" name="Purchase $" radius={[4, 4, 0, 0]}>
                      {ISSUER_SHARES.map((r) => (
                        <Cell key={r.issuer} fill={r.fill} />
                      ))}
                    </Bar>
                  </BarChart>
                </ResponsiveContainer>
              </div>
            </ChartCard>
          </div>
        </div>
      )}

      <div className="rounded-xl border border-slate-200 bg-slate-50 px-5 py-4 text-sm text-slate-600">
        <p className="font-medium text-slate-800">Sources & methodology</p>
        <p className="mt-1">{SOURCE_NOTE}</p>
        <ul className="mt-2 flex flex-wrap gap-x-4 gap-y-1">
          {SOURCES.map((s) => (
            <li key={s.url}>
              <a
                href={s.url}
                className="text-sky-700 underline-offset-2 hover:underline"
              >
                {s.label}
              </a>
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

