"use client";

import { useMemo, useState } from "react";
import {
  Area,
  Bar,
  BarChart,
  CartesianGrid,
  Cell,
  ComposedChart,
  Line,
  Pie,
  PieChart,
  ResponsiveContainer,
  Scatter,
  ScatterChart,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import { Tooltip } from "@/components/charts/SortedTooltip";
import {
  DEBT_PRODUCTS,
  DEBT_STRESS_SLEEVES,
  HEADLINE,
  ISSUER_CUMULATIVE,
  ISSUER_SHARES,
  LIQUID_PARKING_AUG,
  LIQUID_PATH,
  SAVE_BORROW_MIRROR,
  SOURCE_NOTE,
  SOURCES,
  TIP_SCATTER,
  TOP_SHARE_SCOREBOARD,
  VINTAGE_DELTAS,
  WEALTH_CONCENTRATION_CURVE,
  WEALTH_SHARES,
  fmtPct,
  fmtTn,
} from "@/data/consumer-finance-markets-concentration-202608-data";

// viz-types: top-1/top-3 grouped bars, tip scatter, liquid path+donut, save-borrow grouped+mirror, issuer cumulative area, debt stress dual bars, vintage delta bars | layout: default

type ViewId = "scoreboard" | "liquid" | "mirror" | "firms";
type ScoreMetric = "top1Pct" | "top3Pct" | "thickTopPct";
type MirrorMetric = "equitySharePct" | "revolvingSharePct" | "depositSharePct";
type DeltaFilter = "all" | "moved" | "sticky";

const SKY = "#0ea5e9";
const ROSE = "#f43f5e";
const VIOLET = "#8b5cf6";
const AMBER = "#f59e0b";
const TEAL = "#14b8a6";

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
